template:
@php
    $first = \WebxUi\Admin\Links\LinkAttributes::of($button_link, $button_url);
    $picture = is_array($image) && ! empty($image['url']) ? $image : null;
    $mark = is_array($logo ?? null) && ! empty($logo['url']) ? $logo : null;
    $html = is_string($body) ? trim($body) : '';
    if ($html !== '' && ! str_starts_with($html, '<')) {
        $html = implode('', array_map(static fn (string $line): string => '<p>'.e(trim($line)).'</p>', preg_split('/\R+/u', $html) ?: []));
    }
@endphp
@if ($picture || $mark || $heading || $html !== '')
<section @class(['b-media-text', 'b-media-text--end' => $side === 'end', 'b-media-text--surface' => $tone === 'surface', 'b-media-text--alone' => ! $picture]) data-wx-block="media-text">
    <div class="b-media-text__grid" @webxReveal('stagger', $no_reveal)>
        @if ($picture)
            <figure class="b-media-text__figure">
                <img class="b-media-text__image" src="{{ $picture['url'] }}" alt="{{ $picture['alt'] ?? '' }}" loading="lazy" @if (! empty($picture['width'])) width="{{ $picture['width'] }}" height="{{ $picture['height'] }}" @endif>
            </figure>
        @endif
        <div class="b-media-text__words site-prose">
            @if ($mark)
                <img class="b-media-text__logo" src="{{ $mark['url'] }}" alt="{{ $mark['alt'] ?? '' }}" loading="lazy" @if (! empty($mark['width'])) width="{{ $mark['width'] }}" height="{{ $mark['height'] }}" @endif>
            @endif
            @if ($heading)
                <h2 class="b-media-text__heading">@webxAccent($heading)</h2>
            @endif
            @if ($html !== '')
                <div class="b-media-text__body">{!! $html !!}</div>
            @endif
            @if ($button_label && $first)
                <p class="b-media-text__actions"><a class="b-media-text__button" {{ $first }}>{{ $button_label }}</a></p>
            @endif
        </div>
    </div>
</section>
@endif

styles:
.b-media-text {
    --media-text-ring: var(--site-color-accent);
    container-type: inline-size;
    padding-block: var(--site-space-6);
}

.b-media-text--surface {
    padding: var(--site-space-5);
    border-radius: var(--site-radius-lg);
    background: var(--site-color-surface);
}

.b-media-text__grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    align-items: center;
    gap: var(--site-space-5);
}

.b-media-text__figure {
    margin: 0;
}

.b-media-text__image {
    width: 100%;
    height: auto;
    border-radius: var(--site-radius-md);
}

.b-media-text__logo {
    width: auto;
    max-width: min(100%, 12rem);
    height: auto;
    max-height: var(--site-space-8);
    margin: 0 0 var(--site-space-4);
    object-fit: contain;
    object-position: left center;
}

.b-media-text__heading {
    margin: 0 0 var(--site-space-3);
    font-size: var(--site-font-size-3);
}

.b-media-text__body > :first-child {
    margin-top: 0;
}

.b-media-text__body > :last-child {
    margin-bottom: 0;
}

.b-media-text__actions {
    margin: var(--site-space-5) 0 0;
}

.b-media-text__button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 44px;
    padding: 0 var(--site-space-5);
    border: 1px solid transparent;
    border-radius: var(--site-radius-md);
    background: var(--site-color-accent);
    color: var(--site-color-accent-contrast);
    font-weight: 600;
    line-height: 1.2;
    text-align: center;
    text-decoration: none;
    transition: background-color var(--site-duration) var(--site-easing), color var(--site-duration) var(--site-easing);
}

.b-media-text__button:hover {
    background: color-mix(in srgb, var(--site-color-accent) 85%, var(--site-color-text));
}

.b-media-text__button:focus-visible {
    outline: 2px solid var(--media-text-ring);
    outline-offset: 2px;
}

.b-media-text__button--quiet,
.b-media-text__button--quiet:hover {
    border-color: currentColor;
    background: transparent;
    color: inherit;
}

@container (min-width: 40rem) {
    .b-media-text__grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: var(--site-space-7);
    }

    .b-media-text--alone .b-media-text__grid {
        grid-template-columns: minmax(0, 42rem);
    }

    .b-media-text--end .b-media-text__figure {
        order: 2;
    }

    .b-media-text--surface {
        padding: var(--site-space-6);
    }
}
